["md"] = "# PROFILE: 9. Охотник: Выживание (Сурв — СТ / АоЕ)\n# CLASS: HUNTER\n# SPEC: Survival\n# MODE: PVE\n\n## SPELL_BOOK\nSPELL MUZZLE = ID:187707 || NAME:\"Намордник\",\"Muzzle\" || CD:15 || USABLE:true || INTERRUPT:true || ICON:1376045\nSPELL INTIMIDATION = ID:19577 || NAME:\"Устрашение\",\"Intimidation\" || CD:60 || USABLE:true || PVP:true || INTERRUPT:true || ICON:132111\nSPELL FREEZING_TRAP = ID:187650 || NAME:\"Замораживающая ловушка\",\"Freezing Trap\" || CD:30 || PVP:true || ICON:135834\nSPELL TAR_TRAP = ID:187698 || NAME:\"Смоляная ловушка\",\"Tar Trap\" || CD:30 || PVP:true || ICON:576309\nSPELL WING_CLIP = ID:195645 || NAME:\"Подрезать крылья\",\"Wing Clip\" || CD:0 || USABLE:true || PVP:true || ICON:132309\nSPELL HARPOON = ID:190925 || NAME:\"Гарпун\",\"Harpoon\" || CD:30 || CHARGES:1 || USABLE:true || ICON:1376040\nSPELL COORDINATED_ASSAULT = ID:360952,266779 || AURA_ID:360952,266779 || AURA_UNIT:player || AURA_DUR:20 || BURST:20 || BOSS:true || NAME:\"Согласованная атака\",\"Coordinated Assault\" || CD:120 || ICON:2065588\nSPELL SPEARHEAD = ID:360966 || AURA_ID:360966 || AURA_UNIT:player || AURA_DUR:12 || BURST:12 || BOSS:true || NAME:\"Острие копья\",\"Spearhead\" || CD:90 || USABLE:true || ICON:4667417\nSPELL FURY_OF_THE_EAGLE = ID:203415 || NAME:\"Ярость орла\",\"Fury of the Eagle\" || CD:45 || LOCK_CHANNEL:true || USABLE:true || ICON:1239829\nSPELL FLANKING_STRIKE = ID:269751 || AURA_ID:459922,260286 || AURA_UNIT:player || AURA_DUR:10 || NAME:\"Удар с фланга\",\"Flanking Strike\" || CD:30 || GAIN:15 || USABLE:true || ICON:236184\nSPELL EXPLOSIVE_SHOT = ID:212431 || AURA_ID:212431 || AURA_UNIT:target || AURA_DUR:3 || NAME:\"Разрывной выстрел\",\"Explosive Shot\" || CD:30 || COST:20 || USABLE:true || ICON:135826\nSPELL WILDFIRE_BOMB = ID:259495 || AURA_ID:269747 || AURA_UNIT:target || AURA_DUR:6 || NAME:\"Бомба дикого огня\",\"Wildfire Bomb\" || CD:18 || CHARGES:2 || HASTED_CD:true || USABLE:true || ICON:2065605\nSPELL KILL_SHOT = ID:320976,53351 || NAME:\"Убийственный выстрел\",\"Kill Shot\" || CD:10 || CHARGES:2 || COST:10 || EXECUTE:true || USABLE:true || ICON:132212\nSPELL KILL_COMMAND = ID:259489,34026 || AURA_ID:260286 || AURA_UNIT:player || AURA_DUR:10 || NAME:\"Команда «Взять!»\",\"Команда \\\"Взять!\\\"\",\"Kill Command\" || CD:6 || CHARGES:2 || HASTED_CD:true || GAIN:15 || USABLE:true || ICON:132176\nSPELL BUTCHERY = ID:212436,187708 || AURA_ID:212436,393933 || AURA_UNIT:target || AURA_DUR:6 || NAME:\"Разделка туш\",\"Освежевание\",\"Butchery\",\"Carve\" || CD:9 || CHARGES:3 || HASTED_CD:true || COST:30 || SPENDER:true || USABLE:true || ICON:999948\nSPELL MONGOOSE_BITE = ID:259387,186270 || AURA_ID:259388 || AURA_UNIT:player || AURA_DUR:14 || NAME:\"Укус мангуста\",\"Удар ящера\",\"Mongoose Bite\",\"Raptor Strike\" || CD:0 || COST:30 || SPENDER:true || FILLER_INTERRUPTIBLE:true || USABLE:true || ICON:132215\nSPELL EXHILARATION = ID:109304 || NAME:\"Живость\",\"Exhilaration\" || CD:120 || ICON:461117\nSPELL ASPECT_OF_THE_TURTLE = ID:186265 || AURA_ID:186265 || AURA_UNIT:player || AURA_DUR:8 || NAME:\"Дух черепахи\",\"Aspect of the Turtle\" || CD:180 || ICON:236159\nSPELL SURVIVAL_OF_THE_FITTEST = ID:264735 || AURA_ID:264735 || AURA_UNIT:player || AURA_DUR:6 || NAME:\"Выживает сильнейший\",\"Survival of the Fittest\" || CD:90 || CHARGES:2 || ICON:136094\nSPELL FEIGN_DEATH = ID:5384 || NAME:\"Притвориться мертвым\",\"Feign Death\" || CD:30 || ICON:132293\nSPELL MEND_PET = ID:136,982 || NAME:\"Лечение питомца\",\"Воскрешение питомца\",\"Mend Pet\",\"Revive Pet\" || CD:10 || ICON:132179\nAURA SERPENT_STING = ID:271788,259491 || AURA_UNIT:target || AURA_DUR:12 || NAME:\"Укус змеи\",\"Serpent Sting\"\nAURA TIP_OF_THE_SPEAR = ID:260286 || AURA_UNIT:player || AURA_DUR:10 || NAME:\"Наконечник копья\",\"Tip of the Spear\"\nAURA MONGOOSE_FURY = ID:259388 || AURA_UNIT:player || AURA_DUR:14 || NAME:\"Ярость мангуста\",\"Mongoose Fury\"\nAURA DEATHBLOW = ID:378770 || AURA_UNIT:player || AURA_DUR:12 || NAME:\"Смертельный удар\",\"Deathblow\"\n\n## CHANNEL_POLICY\nINTERRUPT_CHANNEL_ON_HIGHER_PRIORITY: NONE\nPROTECT_CHANNEL: FURY_OF_THE_EAGLE\n\n## TRACKERS\nTRACK_SAVES: EXHILARATION, SURVIVAL_OF_THE_FITTEST, ASPECT_OF_THE_TURTLE, FEIGN_DEATH\nTRACK_CDS: COORDINATED_ASSAULT, SPEARHEAD, FLANKING_STRIKE, FURY_OF_THE_EAGLE, MUZZLE\nTRACK_DOTS: WILDFIRE_BOMB, SERPENT_STING, EXPLOSIVE_SHOT\n\n## EMERGENCY_SAVE\nIF player.hp_percent <= 20 AND READY(ASPECT_OF_THE_TURTLE) THEN\n    RETURN EMERGENCY(ASPECT_OF_THE_TURTLE)\nELSE IF player.hp_percent <= 35 AND READY(EXHILARATION) THEN\n    RETURN EMERGENCY(EXHILARATION)\nELSE IF player.hp_percent <= 40 AND READY(SURVIVAL_OF_THE_FITTEST) THEN\n    RETURN EMERGENCY(SURVIVAL_OF_THE_FITTEST)\nEND IF\n\n## ROTATION_QUEUE\nIF target.casting_interruptible AND READY(MUZZLE) THEN\n    RETURN CAST(MUZZLE)\nELSE IF PVP AND target.casting_interruptible AND READY(INTIMIDATION) THEN\n    RETURN CAST(INTIMIDATION)\nELSE IF BOSS AND READY(COORDINATED_ASSAULT) THEN\n    RETURN CAST(COORDINATED_ASSAULT)\nELSE IF BOSS AND READY(SPEARHEAD) THEN\n    RETURN CAST(SPEARHEAD)\nELSE IF NOT player.aura(TIP_OF_THE_SPEAR) AND READY(KILL_COMMAND) THEN\n    RETURN CAST(KILL_COMMAND)\nELSE IF PROC(KILL_COMMAND) AND READY(KILL_COMMAND) THEN\n    RETURN CAST(KILL_COMMAND)\nELSE IF CHARGES(WILDFIRE_BOMB) >= 2 AND READY(WILDFIRE_BOMB) THEN\n    RETURN CAST(WILDFIRE_BOMB)\nELSE IF READY(FLANKING_STRIKE) THEN\n    RETURN CAST(FLANKING_STRIKE)\nELSE IF (PROC(KILL_SHOT) OR player.aura(DEATHBLOW).rem > 0) AND READY(KILL_SHOT) THEN\n    RETURN CAST(KILL_SHOT)\nELSE IF USABLE(KILL_SHOT) AND READY(KILL_SHOT) THEN\n    RETURN CAST(KILL_SHOT)\nELSE IF enemies >= 3 AND READY(BUTCHERY) THEN\n    RETURN CAST(BUTCHERY)\nELSE IF READY(EXPLOSIVE_SHOT) THEN\n    RETURN CAST(EXPLOSIVE_SHOT)\nELSE IF READY(WILDFIRE_BOMB) THEN\n    RETURN CAST(WILDFIRE_BOMB)\nELSE IF READY(FURY_OF_THE_EAGLE) THEN\n    RETURN CAST(FURY_OF_THE_EAGLE)\nELSE IF player.aura(MONGOOSE_FURY).stacks >= 5 AND USABLE(MONGOOSE_BITE) THEN\n    RETURN CAST(MONGOOSE_BITE)\nELSE IF (enemies >= 2 OR CHARGES(BUTCHERY) >= 3) AND READY(BUTCHERY) THEN\n    RETURN CAST(BUTCHERY)\nELSE IF target.aura(SERPENT_STING).rem <= 2 AND USABLE(MONGOOSE_BITE) THEN\n    RETURN CAST(MONGOOSE_BITE)\nELSE IF READY(KILL_COMMAND) THEN\n    RETURN CAST(KILL_COMMAND)\nELSE\n    RETURN CAST(MONGOOSE_BITE)\nEND IF",
["title"] = "9. Охотник: Выживание (Сурв — СТ / АоЕ)",
