["DRUID_02_BALANCE_PVE"] = {
["md"] = "# PROFILE: 6. Друид: Баланс (Сова — СТ / АоЕ)\n# CLASS: DRUID\n# SPEC: Balance\n# MODE: PVE\n\n## SPELL_BOOK\nSPELL MOONKIN_FORM = ID:24858,197625 | AURA_ID:24858,197625 | AURA_UNIT:player | AURA_DUR:3600 | NAME:\"Облик лунного совуха\",\"Moonkin Form\" | CD:0 | ICON:136036\nSPELL SOLAR_BEAM = ID:78675 | NAME:\"Столп солнечного света\",\"Solar Beam\" | CD:60 | INTERRUPT:true | ICON:252188\nSPELL MIGHTY_BASH = ID:5211,132469,33786 | NAME:\"Мощное оглушение\",\"Тайфун\",\"Смерч\",\"Mighty Bash\",\"Typhoon\",\"Cyclone\" | CD:30 | PVP:true | ICON:132114\nSPELL CELESTIAL_ALIGNMENT = ID:194223,102560,383410,390414,1249658 | AURA_ID:194223,102560,383410,390414,1249658 | AURA_UNIT:player | AURA_DUR:15 | BURST:15 | BOSS:true | NAME:\"Парад планет\",\"Воплощение: избранный Элуны\",\"Перевоплощение: избранный Элуны\",\"Celestial Alignment\",\"Incarnation: Chosen of Elune\" | CD:120 | CHARGES:2 | ICON:136060\nSPELL SOLAR_ECLIPSE = ID:1233346,1233272,48517,48518 | AURA_ID:48517,48518,1233346,1233272 | AURA_UNIT:player | AURA_DUR:15 | NAME:\"Солнечное затмение\",\"Лунное затмение\",\"Затмение\",\"Solar Eclipse\",\"Lunar Eclipse\",\"Eclipse\" | CD:32 | CHARGES:2 | ICON:236216\nSPELL FORCE_OF_NATURE = ID:205636 | AURA_ID:428735,205636 | AURA_UNIT:player | AURA_DUR:10 | BURST:10 | BOSS:true | NAME:\"Сила природы\",\"Force of Nature\" | CD:60 | GAIN:20 | ICON:132129\nSPELL FURY_OF_ELUNE = ID:202770 | AURA_ID:202770 | AURA_UNIT:player | AURA_DUR:8 | BURST:8 | BOSS:true | NAME:\"Ярость Элуны\",\"Fury of Elune\" | CD:60 | GAIN:40 | ICON:132123\nSPELL NEW_MOON = ID:274281,274282,274283 | NAME:\"Новолуние\",\"Полумесяц\",\"Полнолуние\",\"New Moon\",\"Half Moon\",\"Full Moon\" | CD:20 | CHARGES:3 | GAIN:10 | ICON:1392545\nSPELL CONVOKE_THE_SPIRITS = ID:391528 | BOSS:true | NAME:\"Созыв духов\",\"Convoke the Spirits\" | CD:120 | LOCK_CHANNEL:true | ICON:3636839\nSPELL MOONFIRE = ID:8921 | AURA_ID:164812,8921 | AURA_DUR:22 | NAME:\"Лунный огонь\",\"Moonfire\" | CD:0 | GAIN:6 | ICON:136096\nSPELL SUNFIRE = ID:93402 | AURA_ID:164815,93402 | AURA_DUR:18 | NAME:\"Солнечный огонь\",\"Sunfire\" | CD:0 | GAIN:6 | ICON:236216\nSPELL STARFALL = ID:191034 | AURA_ID:191034 | AURA_UNIT:player | AURA_DUR:8 | NAME:\"Звездопад\",\"Starfall\" | CD:0 | COST:50 | SPENDER:true | ICON:236168\nSPELL STARSURGE = ID:78674 | NAME:\"Звездный поток\",\"Starsurge\" | CD:0 | COST:40 | SPENDER:true | ICON:135730\nSPELL STARFIRE = ID:194153 | NAME:\"Звездный огонь\",\"Starfire\" | CD:0 | GAIN:10 | ICON:135753\nSPELL WRATH = ID:190984,5176 | NAME:\"Гнев\",\"Wrath\" | CD:0 | GAIN:8 | FILLER_INTERRUPTIBLE:true | ICON:136006\nSPELL BARKSKIN = ID:22812 | NAME:\"Дубовая кожа\",\"Barkskin\" | CD:60 | ICON:136097\nSPELL REGROWTH = ID:8936 | NAME:\"Восстановление\",\"Regrowth\" | CD:0 | ICON:136085\nSPELL BEAR_FORM = ID:5487 | AURA_ID:5487 | AURA_UNIT:player | AURA_DUR:3600 | NAME:\"Облик медведя\",\"Bear Form\" | CD:0 | ICON:132276\n\n## CHANNEL_POLICY\nPROTECT_CHANNEL: CONVOKE_THE_SPIRITS\n\n## TRACKERS\nTRACK_SAVES: BARKSKIN, REGROWTH, BEAR_FORM, SOLAR_BEAM\nTRACK_CDS: CELESTIAL_ALIGNMENT, FORCE_OF_NATURE, FURY_OF_ELUNE, CONVOKE_THE_SPIRITS, SOLAR_ECLIPSE, NEW_MOON\nTRACK_DOTS: MOONFIRE, SUNFIRE\n\n## EMERGENCY_SAVE\nIF player.hp_percent <= 40 AND READY(BARKSKIN) THEN\n    RETURN EMERGENCY(BARKSKIN)\nELSE IF player.hp_percent <= 30 AND READY(REGROWTH) THEN\n    RETURN EMERGENCY(REGROWTH)\nEND IF\n\n## ROTATION_QUEUE\nIF target.casting_interruptible AND READY(SOLAR_BEAM) THEN\n    RETURN CAST(SOLAR_BEAM)\nELSE IF PVP AND READY(MIGHTY_BASH) THEN\n    RETURN CAST(MIGHTY_BASH)\nELSE IF NOT player.aura(MOONKIN_FORM) AND READY(MOONKIN_FORM) THEN\n    RETURN CAST(MOONKIN_FORM)\nELSE IF target.aura(SUNFIRE).rem <= 3 AND READY(SUNFIRE) THEN\n    RETURN CAST(SUNFIRE)\nELSE IF target.aura(MOONFIRE).rem <= 3 AND READY(MOONFIRE) THEN\n    RETURN CAST(MOONFIRE)\nELSE IF PROC(STARFALL) AND enemies >= 2 AND READY(STARFALL) THEN\n    RETURN CAST(STARFALL)\nELSE IF PROC(STARSURGE) AND READY(STARSURGE) THEN\n    RETURN CAST(STARSURGE)\nELSE IF BOSS AND NOT ACTIVE(CELESTIAL_ALIGNMENT) AND READY(CELESTIAL_ALIGNMENT) THEN\n    RETURN CAST(CELESTIAL_ALIGNMENT)\nELSE IF BOSS AND READY(FORCE_OF_NATURE) THEN\n    RETURN CAST(FORCE_OF_NATURE)\nELSE IF BOSS AND READY(FURY_OF_ELUNE) THEN\n    RETURN CAST(FURY_OF_ELUNE)\nELSE IF NOT player.aura(SOLAR_ECLIPSE) AND NOT player.aura(CELESTIAL_ALIGNMENT) AND READY(SOLAR_ECLIPSE) THEN\n    RETURN CAST(SOLAR_ECLIPSE)\nELSE IF BOSS AND player.astral_power <= 50 AND READY(CONVOKE_THE_SPIRITS) THEN\n    RETURN CAST(CONVOKE_THE_SPIRITS)\nELSE IF enemies >= 2 AND USABLE(STARFALL) THEN\n    RETURN CAST(STARFALL)\nELSE IF USABLE(STARSURGE) THEN\n    RETURN CAST(STARSURGE)\nELSE IF READY(NEW_MOON) THEN\n    RETURN CAST(NEW_MOON)\nELSE IF PROC(STARFIRE) AND READY(STARFIRE) THEN\n    RETURN CAST(STARFIRE)\nELSE IF enemies >= 2 AND READY(STARFIRE) THEN\n    RETURN CAST(STARFIRE)\nELSE\n    RETURN CAST(WRATH)\nEND IF\n",
["title"] = "6. Друид: Баланс (Сова — СТ / АоЕ)",
["userModified"] = false,
["id"] = "DRUID_02_BALANCE_PVE",
["class"] = "DRUID",
["mode"] = "PVE",
},
["HUNTER_CUSTOM_10"] = {
["md"] = "# PROFILE: 9. Охотник: Выживание (Сурв — СТ / АоЕ)\n# CLASS: HUNTER\n# SPEC: Survival\n# MODE: PVE\n\n## SPELL_BOOK\nSPELL MUZZLE = ID:187707 || NAME:\"Намордник\",\"Muzzle\" || CD:15 || USABLE:true || INTERRUPT:true || ICON:1376045\nSPELL INTIMIDATION = ID:19577 || NAME:\"Устрашение\",\"Intimidation\" || CD:60 || USABLE:true || PVP:true || INTERRUPT:true || ICON:132111\nSPELL FREEZING_TRAP = ID:187650 || NAME:\"Замораживающая ловушка\",\"Freezing Trap\" || CD:30 || PVP:true || ICON:135834\nSPELL TAR_TRAP = ID:187698 || NAME:\"Смоляная ловушка\",\"Tar Trap\" || CD:30 || PVP:true || ICON:576309\nSPELL WING_CLIP = ID:195645 || NAME:\"Подрезать крылья\",\"Wing Clip\" || CD:0 || USABLE:true || PVP:true || ICON:132309\nSPELL HARPOON = ID:190925 || NAME:\"Гарпун\",\"Harpoon\" || CD:30 || CHARGES:1 || USABLE:true || ICON:1376040\nSPELL COORDINATED_ASSAULT = ID:360952,266779 || AURA_ID:360952,266779 || AURA_UNIT:player || AURA_DUR:20 || BURST:20 || BOSS:true || NAME:\"Согласованная атака\",\"Coordinated Assault\" || CD:120 || ICON:2065588\nSPELL SPEARHEAD = ID:360966 || AURA_ID:360966 || AURA_UNIT:player || AURA_DUR:12 || BURST:12 || BOSS:true || NAME:\"Острие копья\",\"Spearhead\" || CD:90 || USABLE:true || ICON:4667417\nSPELL FURY_OF_THE_EAGLE = ID:203415 || NAME:\"Ярость орла\",\"Fury of the Eagle\" || CD:45 || LOCK_CHANNEL:true || USABLE:true || ICON:1239829\nSPELL FLANKING_STRIKE = ID:269751 || AURA_ID:459922,260286 || AURA_UNIT:player || AURA_DUR:10 || NAME:\"Удар с фланга\",\"Flanking Strike\" || CD:30 || GAIN:15 || USABLE:true || ICON:236184\nSPELL EXPLOSIVE_SHOT = ID:212431 || AURA_ID:212431 || AURA_UNIT:target || AURA_DUR:3 || NAME:\"Разрывной выстрел\",\"Explosive Shot\" || CD:30 || COST:20 || USABLE:true || ICON:135826\nSPELL WILDFIRE_BOMB = ID:259495 || AURA_ID:269747 || AURA_UNIT:target || AURA_DUR:6 || NAME:\"Бомба дикого огня\",\"Wildfire Bomb\" || CD:18 || CHARGES:2 || HASTED_CD:true || USABLE:true || ICON:2065605\nSPELL KILL_SHOT = ID:320976,53351 || NAME:\"Убийственный выстрел\",\"Kill Shot\" || CD:10 || CHARGES:2 || COST:10 || EXECUTE:true || USABLE:true || ICON:132212\nSPELL KILL_COMMAND = ID:259489,34026 || AURA_ID:260286 || AURA_UNIT:player || AURA_DUR:10 || NAME:\"Команда «Взять!»\",\"Команда \\\"Взять!\\\"\",\"Kill Command\" || CD:6 || CHARGES:2 || HASTED_CD:true || GAIN:15 || USABLE:true || ICON:132176\nSPELL BUTCHERY = ID:212436,187708 || AURA_ID:212436,393933 || AURA_UNIT:target || AURA_DUR:6 || NAME:\"Разделка туш\",\"Освежевание\",\"Butchery\",\"Carve\" || CD:9 || CHARGES:3 || HASTED_CD:true || COST:30 || SPENDER:true || USABLE:true || ICON:999948\nSPELL MONGOOSE_BITE = ID:259387,186270 || AURA_ID:259388 || AURA_UNIT:player || AURA_DUR:14 || NAME:\"Укус мангуста\",\"Удар ящера\",\"Mongoose Bite\",\"Raptor Strike\" || CD:0 || COST:30 || SPENDER:true || FILLER_INTERRUPTIBLE:true || USABLE:true || ICON:132215\nSPELL EXHILARATION = ID:109304 || NAME:\"Живость\",\"Exhilaration\" || CD:120 || ICON:461117\nSPELL ASPECT_OF_THE_TURTLE = ID:186265 || AURA_ID:186265 || AURA_UNIT:player || AURA_DUR:8 || NAME:\"Дух черепахи\",\"Aspect of the Turtle\" || CD:180 || ICON:236159\nSPELL SURVIVAL_OF_THE_FITTEST = ID:264735 || AURA_ID:264735 || AURA_UNIT:player || AURA_DUR:6 || NAME:\"Выживает сильнейший\",\"Survival of the Fittest\" || CD:90 || CHARGES:2 || ICON:136094\nSPELL FEIGN_DEATH = ID:5384 || NAME:\"Притвориться мертвым\",\"Feign Death\" || CD:30 || ICON:132293\nSPELL MEND_PET = ID:136,982 || NAME:\"Лечение питомца\",\"Воскрешение питомца\",\"Mend Pet\",\"Revive Pet\" || CD:10 || ICON:132179\nAURA SERPENT_STING = ID:271788,259491 || AURA_UNIT:target || AURA_DUR:12 || NAME:\"Укус змеи\",\"Serpent Sting\"\nAURA TIP_OF_THE_SPEAR = ID:260286 || AURA_UNIT:player || AURA_DUR:10 || NAME:\"Наконечник копья\",\"Tip of the Spear\"\nAURA MONGOOSE_FURY = ID:259388 || AURA_UNIT:player || AURA_DUR:14 || NAME:\"Ярость мангуста\",\"Mongoose Fury\"\nAURA DEATHBLOW = ID:378770 || AURA_UNIT:player || AURA_DUR:12 || NAME:\"Смертельный удар\",\"Deathblow\"\n\n## CHANNEL_POLICY\nINTERRUPT_CHANNEL_ON_HIGHER_PRIORITY: NONE\nPROTECT_CHANNEL: FURY_OF_THE_EAGLE\n\n## TRACKERS\nTRACK_SAVES: EXHILARATION, SURVIVAL_OF_THE_FITTEST, ASPECT_OF_THE_TURTLE, FEIGN_DEATH\nTRACK_CDS: COORDINATED_ASSAULT, SPEARHEAD, FLANKING_STRIKE, FURY_OF_THE_EAGLE, MUZZLE\nTRACK_DOTS: WILDFIRE_BOMB, SERPENT_STING, EXPLOSIVE_SHOT\n\n## EMERGENCY_SAVE\nIF player.hp_percent <= 20 AND READY(ASPECT_OF_THE_TURTLE) THEN\n    RETURN EMERGENCY(ASPECT_OF_THE_TURTLE)\nELSE IF player.hp_percent <= 35 AND READY(EXHILARATION) THEN\n    RETURN EMERGENCY(EXHILARATION)\nELSE IF player.hp_percent <= 40 AND READY(SURVIVAL_OF_THE_FITTEST) THEN\n    RETURN EMERGENCY(SURVIVAL_OF_THE_FITTEST)\nEND IF\n\n## ROTATION_QUEUE\nIF target.casting_interruptible AND READY(MUZZLE) THEN\n    RETURN CAST(MUZZLE)\nELSE IF PVP AND target.casting_interruptible AND READY(INTIMIDATION) THEN\n    RETURN CAST(INTIMIDATION)\nELSE IF BOSS AND READY(COORDINATED_ASSAULT) THEN\n    RETURN CAST(COORDINATED_ASSAULT)\nELSE IF BOSS AND READY(SPEARHEAD) THEN\n    RETURN CAST(SPEARHEAD)\nELSE IF NOT player.aura(TIP_OF_THE_SPEAR) AND READY(KILL_COMMAND) THEN\n    RETURN CAST(KILL_COMMAND)\nELSE IF PROC(KILL_COMMAND) AND READY(KILL_COMMAND) THEN\n    RETURN CAST(KILL_COMMAND)\nELSE IF CHARGES(WILDFIRE_BOMB) >= 2 AND READY(WILDFIRE_BOMB) THEN\n    RETURN CAST(WILDFIRE_BOMB)\nELSE IF READY(FLANKING_STRIKE) THEN\n    RETURN CAST(FLANKING_STRIKE)\nELSE IF (PROC(KILL_SHOT) OR player.aura(DEATHBLOW).rem > 0) AND READY(KILL_SHOT) THEN\n    RETURN CAST(KILL_SHOT)\nELSE IF USABLE(KILL_SHOT) AND READY(KILL_SHOT) THEN\n    RETURN CAST(KILL_SHOT)\nELSE IF enemies >= 3 AND READY(BUTCHERY) THEN\n    RETURN CAST(BUTCHERY)\nELSE IF READY(EXPLOSIVE_SHOT) THEN\n    RETURN CAST(EXPLOSIVE_SHOT)\nELSE IF READY(WILDFIRE_BOMB) THEN\n    RETURN CAST(WILDFIRE_BOMB)\nELSE IF READY(FURY_OF_THE_EAGLE) THEN\n    RETURN CAST(FURY_OF_THE_EAGLE)\nELSE IF player.aura(MONGOOSE_FURY).stacks >= 5 AND USABLE(MONGOOSE_BITE) THEN\n    RETURN CAST(MONGOOSE_BITE)\nELSE IF (enemies >= 2 OR CHARGES(BUTCHERY) >= 3) AND READY(BUTCHERY) THEN\n    RETURN CAST(BUTCHERY)\nELSE IF target.aura(SERPENT_STING).rem <= 2 AND USABLE(MONGOOSE_BITE) THEN\n    RETURN CAST(MONGOOSE_BITE)\nELSE IF READY(KILL_COMMAND) THEN\n    RETURN CAST(KILL_COMMAND)\nELSE\n    RETURN CAST(MONGOOSE_BITE)\nEND IF",
["title"] = "9. Охотник: Выживание (Сурв — СТ / АоЕ)",
["userModified"] = true,
["id"] = "HUNTER_CUSTOM_10",
["class"] = "HUNTER",
["isCustom"] = true,
["mode"] = "PVE",
},
["WARRIOR_02_ARGS_BOSS"] = {
["md"] = "# PROFILE: 4. Воин: Оружие (Армс — СТ / АоЕ)\n# CLASS: WARRIOR\n# SPEC: Arms\n# MODE: PVE\n\n## SPELL_BOOK\nSPELL PUMMEL = ID:6552 | NAME:\"Зуботычина\",\"Pummel\" | CD:15 | INTERRUPT:true | ICON:132938\nSPELL STORM_BOLT = ID:107570,1715 | NAME:\"Удар громовержца\",\"Подрезать сухожилия\",\"Storm Bolt\",\"Hamstring\" | CD:30 | PVP:true | ICON:613535\nSPELL COLOSSUS_SMASH = ID:167105,262161,436358 | AURA_ID:208086 | AURA_DUR:10 | BURST:10 | NAME:\"Удар колосса\",\"Миротворец\",\"Сокрушение\",\"Colossus Smash\",\"Warbreaker\",\"Demolish\" | CD:45 | CHARGES:1 | ICON:132355\nSPELL BLADESTORM = ID:227847,389774,228920 | BOSS:true | NAME:\"Вихрь клинков\",\"Опустошитель\",\"Bladestorm\",\"Ravager\" | CD:90 | CHARGES:1 | ICON:236303\nSPELL EXECUTE = ID:163201,5308,281000 | NAME:\"Казнь\",\"Execute\" | CD:0 | CHARGES:1 | EXECUTE:true | ICON:135358\nSPELL SWEEPING_STRIKES = ID:260708 | AURA_ID:260708 | AURA_UNIT:player | AURA_DUR:15 | NAME:\"Размашистые удары\",\"Sweeping Strikes\" | CD:30 | CHARGES:1 | ICON:132366\nSPELL REND = ID:772,384318,376079 | AURA_ID:772,388539 | AURA_DUR:15 | NAME:\"Кровопускание\",\"Громогласный рык\",\"Копье чемпиона\",\"Rend\",\"Thunderous Roar\",\"Champion's Spear\" | CD:0 | CHARGES:1 | ICON:132155\nSPELL AVATAR = ID:107574 | AURA_ID:107574 | AURA_UNIT:player | AURA_DUR:20 | BURST:20 | BOSS:true | NAME:\"Аватара\",\"Avatar\" | CD:90 | CHARGES:1 | ICON:613534\nSPELL MORTAL_STRIKE = ID:12294 | NAME:\"Смертельный удар\",\"Mortal Strike\" | CD:6 | CHARGES:1 | ICON:132355\nSPELL OVERPOWER = ID:7384 | NAME:\"Превосходство\",\"Overpower\" | CD:12 | CHARGES:2 | ICON:132223\nSPELL CLEAVE = ID:845 | NAME:\"Рассекающий удар\",\"Cleave\" | CD:4.5 | CHARGES:1 | ICON:132338\nSPELL SLAM = ID:1680,1464,6343 | NAME:\"Вихрь\",\"Мощный удар\",\"Удар грома\",\"Whirlwind\",\"Slam\",\"Thunder Clap\" | CD:0 | CHARGES:1 | FILLER_INTERRUPTIBLE:true | ICON:132369\nSPELL DIE_BY_THE_SWORD = ID:118038 | NAME:\"Бой насмерть\",\"Die by the Sword\" | CD:120 | CHARGES:1 | ICON:132336\nSPELL RALLYING_CRY = ID:97462,383762 | NAME:\"Ободряющий клич\",\"Горестная невосприимчивость\",\"Rallying Cry\",\"Bitter Immunity\" | CD:180 | CHARGES:1 | ICON:132351\nSPELL SPELL_REFLECTION = ID:23920 | NAME:\"Отражение заклинаний\",\"Spell Reflection\" | CD:25 | CHARGES:1 | ICON:132361\nSPELL IMPENDING_VICTORY = ID:202168 | NAME:\"Верная победа\",\"Impending Victory\" | CD:25 | CHARGES:1 | ICON:589768\n\n## TRACKERS\nTRACK_SAVES: DIE_BY_THE_SWORD, RALLYING_CRY, SPELL_REFLECTION, IMPENDING_VICTORY\nTRACK_CDS: AVATAR, COLOSSUS_SMASH, BLADESTORM, SWEEPING_STRIKES, PUMMEL\nTRACK_DOTS: REND, COLOSSUS_SMASH\n\n## EMERGENCY_SAVE\nIF player.hp_percent <= 25 AND READY(DIE_BY_THE_SWORD) THEN\n    RETURN EMERGENCY(DIE_BY_THE_SWORD)\nELSE IF player.hp_percent <= 35 AND READY(IMPENDING_VICTORY) THEN\n    RETURN EMERGENCY(IMPENDING_VICTORY)\nEND IF\n\n## ROTATION_QUEUE\nIF target.casting_interruptible AND READY(PUMMEL) THEN\n    RETURN CAST(PUMMEL)\nELSE IF PVP AND READY(STORM_BOLT) THEN\n    RETURN CAST(STORM_BOLT)\nELSE IF enemies >= 2 AND READY(SWEEPING_STRIKES) THEN\n    RETURN CAST(SWEEPING_STRIKES)\nELSE IF BOSS AND READY(AVATAR) THEN\n    RETURN CAST(AVATAR)\nELSE IF PROC(EXECUTE) AND READY(EXECUTE) THEN\n    RETURN CAST(EXECUTE)\nELSE IF USABLE(EXECUTE) AND READY(EXECUTE) THEN\n    RETURN CAST(EXECUTE)\nELSE IF target.aura(REND).rem <= 1 AND READY(REND) THEN\n    RETURN CAST(REND)\nELSE IF READY(COLOSSUS_SMASH) THEN\n    RETURN CAST(COLOSSUS_SMASH)\nELSE IF enemies >= 3 AND READY(CLEAVE) THEN\n    RETURN CAST(CLEAVE)\nELSE IF READY(MORTAL_STRIKE) THEN\n    RETURN CAST(MORTAL_STRIKE)\nELSE IF BOSS AND READY(BLADESTORM) THEN\n    RETURN CAST(BLADESTORM)\nELSE IF READY(OVERPOWER) THEN\n    RETURN CAST(OVERPOWER)\nELSE IF READY(CLEAVE) THEN\n    RETURN CAST(CLEAVE)\nELSE\n    RETURN CAST(SLAM)\nEND IF\n",
["title"] = "4. Воин: Оружие (Армс — СТ / АоЕ)",
["userModified"] = false,
["id"] = "WARRIOR_02_ARGS_BOSS",
["class"] = "WARRIOR",
