},
["PRIEST_01_SHADOW_PVE"] = {
["md"] = "# PROFILE: 1. Жрец: Тьма (ШП — Левелинг / СТ / АоЕ)\n# CLASS: PRIEST\n# SPEC: Shadow\n# MODE: PVE\n\n## SPELL_BOOK\nSPELL SHADOWFORM = ID:232698 | AURA_ID:232698 | AURA_UNIT:player | AURA_DUR:3600 | NAME:\"Облик Тьмы\",\"Shadowform\" | CD:0 | ICON:136200\nSPELL SILENCE = ID:15487 | NAME:\"Безмолвие\",\"Silence\" | CD:45 | INTERRUPT:true | ICON:458230\nSPELL PSYCHIC_HORROR = ID:64044,8122 | NAME:\"Глубинный ужас\",\"Ментальный крик\",\"Psychic Horror\",\"Psychic Scream\" | CD:45 | PVP:true | ICON:237568\nSPELL TENTACLE_SLAM = ID:1227280,205385,457042,1234796 | AURA_ID:34914 | AURA_DUR:21 | NAME:\"Мощный удар щупальцем\",\"Темное сокрушение\",\"Shadow Crash\",\"Tentacle Slam\" | CD:15 | CHARGES:2 | HASTED_CD:true | ONCE_PER_QUEUE:true | GAIN:15 | ICON:136201\nSPELL VAMPIRIC_TOUCH = ID:34914 | AURA_ID:34914 | AURA_DUR:21 | NAME:\"Прикосновение вампира\",\"Vampiric Touch\" | CD:0 | CHARGES:1 | GAIN:6 | ICON:135978\nSPELL SHADOW_WORD_PAIN = ID:589 | AURA_ID:589 | AURA_UNIT:target | AURA_DUR:16 | NAME:\"Слово Тьмы: Боль\",\"Shadow Word: Pain\" | CD:0 | GAIN:4 | ICON:136207\nSPELL VOID_ERUPTION = ID:228260,391109,194249 | AURA_ID:194249,391109 | AURA_UNIT:player | AURA_DUR:20 | BURST:20 | BOSS:true | NAME:\"Облик Бездны\",\"Извержение Бездны\",\"Темное вознесение\",\"Voidform\",\"Void Eruption\",\"Dark Ascension\" | CD:120 | ICON:537079\nSPELL POWER_INFUSION = ID:10060 | AURA_ID:10060 | AURA_UNIT:player | AURA_DUR:15 | BURST:15 | BOSS:true | NAME:\"Придание сил\",\"Power Infusion\" | CD:120 | ICON:135939\nSPELL VOID_BOLT = ID:1242173,205448 | NAME:\"Залп Бездны\",\"Стрела Бездны\",\"Void Volley\",\"Void Bolt\" | CD:6 | GAIN:10 | OVERRIDE_OF:VOID_ERUPTION | PROC_ONLY:true | ICON:1386548\nSPELL DEVOURING_PLAGUE = ID:335467 | AURA_ID:335467 | AURA_DUR:6 | NAME:\"Слово Тьмы: Безумие\",\"Всепожирающая чума\",\"Shadow Word: Madness\",\"Devouring Plague\" | CD:0 | COST:50 | SPENDER:true | ICON:252997\nSPELL SHADOW_WORD_DEATH = ID:32379 | NAME:\"Слово Тьмы: Смерть\",\"Shadow Word: Death\" | CD:10 | GAIN:10 | EXECUTE:true | ICON:136149\nSPELL MIND_BLAST = ID:450983,8092 | NAME:\"Выброс Бездны\",\"Взрыв разума\",\"Void Blast\",\"Mind Blast\" | CD:7.5 | CHARGES:1 | HASTED_CD:true | GAIN:15 | ICON:136224\nSPELL VOID_TORRENT = ID:263165 | NAME:\"Поток бездны\",\"Поток Бездны\",\"Void Torrent\" | CD:45 | CHARGES:1 | GAIN:35 | LOCK_CHANNEL:true | ICON:1386551\nSPELL MIND_FLAY_INSANITY = ID:391403 | NAME:\"Пытка разума: безумие\",\"Mind Flay: Insanity\" | CD:0 | GAIN:16 | OVERRIDE_OF:MIND_FLAY | PROC_ONLY:true | ICON:136208\nSPELL MIND_FLAY = ID:15407 | NAME:\"Пытка разума\",\"Mind Flay\" | CD:0 | GAIN:12 | FILLER_INTERRUPTIBLE:true | ICON:136208\nSPELL PSYFIEND = ID:34433,211522,375901,451235,200174 | BOSS:true | NAME:\"Исчадие Тьмы\",\"Ментальный демон\",\"Игры разума\",\"Призрак Бездны\",\"Shadowfiend\",\"Psyfiend\" | CD:60 | ICON:136199\nSPELL DISPERSION = ID:47585 | NAME:\"Слияние с тьмой\",\"Слияние с Тьмой\",\"Dispersion\" | CD:90 | ICON:237563\nSPELL DESPERATE_PRAYER = ID:19236 | NAME:\"Молитва отчаяния\",\"Desperate Prayer\" | CD:90 | ICON:237550\nSPELL VAMPIRIC_EMBRACE = ID:15286 | NAME:\"Объятия вампира\",\"Vampiric Embrace\" | CD:120 | ICON:136230\nSPELL FADE = ID:586,8122 | NAME:\"Уход в тень\",\"Ментальный крик\",\"Fade\",\"Psychic Scream\" | CD:30 | ICON:135994\nSPELL POWER_WORD_SHIELD = ID:17 | NAME:\"Слово силы: Щит\",\"Power Word: Shield\" | CD:7.5 | ICON:135940\n\n## CHANNEL_POLICY\nINTERRUPT_CHANNEL_ON_HIGHER_PRIORITY: MIND_FLAY\nPROTECT_CHANNEL: VOID_TORRENT\n\n## TRACKERS\nTRACK_SAVES: DISPERSION, DESPERATE_PRAYER, VAMPIRIC_EMBRACE, FADE\nTRACK_CDS: POWER_INFUSION, VOID_ERUPTION, VOID_TORRENT, PSYFIEND, SILENCE\nTRACK_DOTS: VAMPIRIC_TOUCH, SHADOW_WORD_PAIN, DEVOURING_PLAGUE\n\n## EMERGENCY_SAVE\nIF player.hp_percent <= 20 AND READY(DISPERSION) THEN\n    RETURN EMERGENCY(DISPERSION)\nELSE IF player.hp_percent <= 25 AND READY(DESPERATE_PRAYER) THEN\n    RETURN EMERGENCY(DESPERATE_PRAYER)\nELSE IF player.hp_percent <= 25 AND READY(VAMPIRIC_EMBRACE) THEN\n    RETURN EMERGENCY(VAMPIRIC_EMBRACE)\nEND IF\n\n## ROTATION_QUEUE\nIF target.casting_interruptible AND READY(SILENCE) THEN\n    RETURN CAST(SILENCE)\nELSE IF PVP AND target.casting_interruptible AND READY(PSYCHIC_HORROR) THEN\n    RETURN CAST(PSYCHIC_HORROR)\nELSE IF NOT player.aura(SHADOWFORM) AND NOT player.aura(VOID_ERUPTION) AND READY(SHADOWFORM) THEN\n    RETURN CAST(SHADOWFORM)\nELSE IF target.aura(VAMPIRIC_TOUCH).rem <= 1 AND READY(TENTACLE_SLAM) THEN\n    RETURN CAST(TENTACLE_SLAM)\nELSE IF target.aura(VAMPIRIC_TOUCH).rem <= 1 AND NOT READY(TENTACLE_SLAM) THEN\n    RETURN CAST(VAMPIRIC_TOUCH)\nELSE IF target.aura(SHADOW_WORD_PAIN).rem <= 1 AND READY(SHADOW_WORD_PAIN) THEN\n    RETURN CAST(SHADOW_WORD_PAIN)\nELSE IF BOSS AND READY(VOID_ERUPTION) THEN\n    RETURN CAST(VOID_ERUPTION)\nELSE IF BOSS AND READY(POWER_INFUSION) THEN\n    RETURN CAST(POWER_INFUSION)\nELSE IF BOSS AND READY(PSYFIEND) THEN\n    RETURN CAST(PSYFIEND)\nELSE IF PROC(VOID_BOLT) AND READY(VOID_BOLT) THEN\n    RETURN CAST(VOID_BOLT)\nELSE IF PROC(DEVOURING_PLAGUE) AND USABLE(DEVOURING_PLAGUE) THEN\n    RETURN CAST(DEVOURING_PLAGUE)\nELSE IF PROC(SHADOW_WORD_DEATH) AND READY(SHADOW_WORD_DEATH) THEN\n    RETURN CAST(SHADOW_WORD_DEATH)\nELSE IF USABLE(SHADOW_WORD_DEATH) AND READY(SHADOW_WORD_DEATH) THEN\n    RETURN CAST(SHADOW_WORD_DEATH)\nELSE IF PROC(MIND_BLAST) AND READY(MIND_BLAST) THEN\n    RETURN CAST(MIND_BLAST)\nELSE IF USABLE(DEVOURING_PLAGUE) THEN\n    RETURN CAST(DEVOURING_PLAGUE)\nELSE IF READY(VOID_TORRENT) THEN\n    RETURN CAST(VOID_TORRENT)\nELSE IF READY(MIND_BLAST) THEN\n    RETURN CAST(MIND_BLAST)\nELSE IF READY(TENTACLE_SLAM) THEN\n    RETURN CAST(TENTACLE_SLAM)\nELSE IF PROC(MIND_FLAY_INSANITY) THEN\n    RETURN CAST(MIND_FLAY_INSANITY)\nELSE\n    RETURN CAST(MIND_FLAY)\nEND IF\n",
["title"] = "1. Жрец: Тьма (ШП — Левелинг / СТ / АоЕ)",
["userModified"] = false,
["id"] = "PRIEST_01_SHADOW_PVE",
["class"] = "PRIEST",
["mode"] = "PVE",
},
["MONK_01_WW_PVE"] = {
["md"] = "# PROFILE: 8. Монах: Танцующий с ветром (ВВ — СТ / АоЕ)\n# CLASS: MONK\n# SPEC: Windwalker\n# MODE: PVE\n# COMBO_STRIKES: true\n\n## SPELL_BOOK\nSPELL SPEAR_HAND_STRIKE = ID:116705 | NAME:\"Рука-копье\",\"Spear Hand Strike\" | CD:15 | USABLE:true | INTERRUPT:true | ICON:608940\nSPELL LEG_SWEEP = ID:119381 | NAME:\"Круговой удар ногой\",\"Leg Sweep\" | CD:60 | USABLE:true | INTERRUPT:true | ICON:642414\nSPELL PARALYSIS = ID:115078 | NAME:\"Паралич\",\"Paralysis\" | CD:45 | USABLE:true | PVP:true | INTERRUPT:true | ICON:629534\nSPELL DISABLE = ID:116095 | NAME:\"Вывести из строя\",\"Disable\" | CD:1.0 | USABLE:true | PVP:true | ICON:132316\nSPELL TOUCH_OF_KARMA = ID:122470 | AURA_ID:125174,122470 | AURA_UNIT:player | AURA_DUR:10 | NAME:\"Закон кармы\",\"Touch of Karma\" | CD:90 | USABLE:true | ICON:651728\nSPELL FORTIFYING_BREW = ID:115203,243435 | AURA_ID:120954,243435 | AURA_UNIT:player | AURA_DUR:15 | NAME:\"Укрепляющий отвар\",\"Fortifying Brew\" | CD:120 | USABLE:true | ICON:611420\nSPELL DIFFUSE_MAGIC = ID:122783 | AURA_ID:122783 | AURA_UNIT:player | AURA_DUR:6 | NAME:\"Распыление магии\",\"Diffuse Magic\" | CD:90 | USABLE:true | ICON:775460\nSPELL DAMPEN_HARM = ID:122278 | AURA_ID:122278 | AURA_UNIT:player | AURA_DUR:10 | NAME:\"Смягчение удара\",\"Dampen Harm\" | CD:120 | USABLE:true | ICON:620827\nSPELL EXPEL_HARM = ID:322101 | NAME:\"Устранение вреда\",\"Expel Harm\" | CD:15 | GAIN:20 | USABLE:true | ICON:627485\nSPELL VIVIFY = ID:116670 | AURA_ID:392883 | AURA_UNIT:player | NAME:\"Оживить\",\"Vivify\" | CD:0 | USABLE:true | ICON:1360980\nSPELL DETOX = ID:218164 | NAME:\"Детоксикация\",\"Detox\" | CD:8 | USABLE:true | ICON:460692\nSPELL TOUCH_OF_DEATH = ID:322109 | NAME:\"Смертельное касание\",\"Touch of Death\" | CD:180 | EXECUTE:true | USABLE:true | ICON:606543\nSPELL INVOKE_XUEN = ID:123904 | AURA_ID:123904 | AURA_UNIT:player | AURA_DUR:20 | BURST:20 | BOSS:true | NAME:\"Призыв Сюэня, Белого Тигра\",\"Invoke Xuen, the White Tiger\" | CD:120 | USABLE:true | ICON:620832\nSPELL STORM_EARTH_AND_FIRE = ID:137639,221771 | AURA_ID:137639 | AURA_UNIT:player | AURA_DUR:15 | BURST:15 | CHARGES:2 | BOSS:true | NAME:\"Буря, земля и огонь\",\"Storm, Earth, and Fire\" | CD:90 | USABLE:true | ICON:136038\nSPELL CELESTIAL_CONDUIT = ID:443028 | AURA_ID:443028 | AURA_UNIT:player | AURA_DUR:4 | LOCK_CHANNEL:true | NAME:\"Небожитель-проводник\",\"Celestial Conduit\" | CD:90 | USABLE:true | ICON:5927619\nSPELL STRIKE_OF_THE_WINDLORD = ID:392983 | NAME:\"Удар Владыки Ветра\",\"Strike of the Windlord\" | CD:30 | SPENDER:true | COST:40 | USABLE:true | ICON:1376045\nSPELL FISTS_OF_FURY = ID:113656 | NAME:\"Неистовые кулаки\",\"Fists of Fury\" | CD:24 | HASTED_CD:true | SPENDER:true | COST:60 | LOCK_CHANNEL:true | USABLE:true | ICON:606541\nSPELL RISING_SUN_KICK = ID:107428 | AURA_ID:115804,107428 | AURA_UNIT:target | AURA_DUR:10 | NAME:\"Удар восходящего солнца\",\"Rising Sun Kick\" | CD:10 | HASTED_CD:true | SPENDER:true | COST:40 | USABLE:true | ICON:606551\nSPELL WHIRLING_DRAGON_PUNCH = ID:152175 | NAME:\"Удар летящего дракона\",\"Whirling Dragon Punch\" | CD:24 | HASTED_CD:true | PROC_ONLY:true | USABLE:true | ICON:988194\nSPELL SLICING_WINDS = ID:442515,442748 | NAME:\"Рассекающие ветра\",\"Slicing Winds\" | CD:30 | USABLE:true | ICON:1029585\nSPELL SPINNING_CRANE_KICK = ID:101546 | AURA_ID:325202 | AURA_UNIT:player | NAME:\"Танцующий журавль\",\"Spinning Crane Kick\" | CD:0 | SPENDER:true | COST:40 | USABLE:true | ICON:606544\nSPELL BLACKOUT_KICK = ID:100784 | AURA_ID:116768 | AURA_UNIT:player | NAME:\"Нокаутирующий удар\",\"Blackout Kick\" | CD:0 | SPENDER:true | COST:20 | USABLE:true | ICON:606540\nSPELL TIGER_PALM = ID:100780 | AURA_ID:202090 | AURA_UNIT:player | AURA_DUR:20 | NAME:\"Лапа тигра\",\"Tiger Palm\" | CD:0 | GAIN:40 | USABLE:true | ICON:606552\nSPELL CRACKLING_JADE_LIGHTNING = ID:117952 | AURA_ID:451433,393039 | AURA_UNIT:player | NAME:\"Сверкающая нефритовая молния\",\"Crackling Jade Lightning\" | CD:0 | FILLER_INTERRUPTIBLE:true | USABLE:true | ICON:606542\nAURA MARK_OF_THE_CRANE = ID:228287 | AURA_UNIT:target | AURA_DUR:15 | NAME:\"Метка журавля\",\"Mark of the Crane\"\nAURA DANCE_OF_CHI_JI = ID:325202 | AURA_UNIT:player | AURA_DUR:15 | NAME:\"Танец Чи-Цзи\",\"Dance of Chi-Ji\"\nAURA BLACKOUT_KICK_PROC = ID:116768 | AURA_UNIT:player | AURA_DUR:15 | NAME:\"Нокаутирующий удар!\",\"Blackout Kick!\"\nAURA TEACHINGS_OF_THE_MONASTERY = ID:202090 | AURA_UNIT:player | AURA_DUR:20 | NAME:\"Учения монастыря\",\"Teachings of the Monastery\"\nAURA VIVACIOUS_VIVIFICATION = ID:392883 | AURA_UNIT:player | AURA_DUR:10 | NAME:\"Бодрящее оживление\",\"Vivacious Vivification\"\nAURA THE_EMPERORS_CAPACITOR = ID:393039,451433 | AURA_UNIT:player | AURA_DUR:20 | NAME:\"Конденсатор императора\",\"The Emperor's Capacitor\"\nAURA MORTAL_WOUNDS = ID:115804 | AURA_UNIT:target | AURA_DUR:10 | NAME:\"Смертельные раны\",\"Mortal Wounds\"\n\n## CHANNEL_POLICY\nINTERRUPT_CHANNEL_ON_HIGHER_PRIORITY: CRACKLING_JADE_LIGHTNING\nPROTECT_CHANNEL: FISTS_OF_FURY, CELESTIAL_CONDUIT\n\n## TRACKERS\nTRACK_SAVES: TOUCH_OF_KARMA, FORTIFYING_BREW, EXPEL_HARM, VIVIFY\nTRACK_CDS: INVOKE_XUEN, STORM_EARTH_AND_FIRE, STRIKE_OF_THE_WINDLORD, CELESTIAL_CONDUIT, TOUCH_OF_DEATH\nTRACK_DOTS: MARK_OF_THE_CRANE, RISING_SUN_KICK\n\n## EMERGENCY_SAVE\nIF player.hp_percent <= 35 AND READY(TOUCH_OF_KARMA) THEN\n    RETURN EMERGENCY(TOUCH_OF_KARMA)\nELSE IF player.hp_percent <= 35 AND READY(FORTIFYING_BREW) THEN\n    RETURN EMERGENCY(FORTIFYING_BREW)\nELSE IF player.hp_percent <= 45 AND READY(EXPEL_HARM) THEN\n    RETURN EMERGENCY(EXPEL_HARM)\nELSE IF player.hp_percent <= 40 AND player.aura(VIVACIOUS_VIVIFICATION).rem > 0 AND READY(VIVIFY) THEN\n    RETURN EMERGENCY(VIVIFY)\nEND IF\n\n## ROTATION_QUEUE\nIF target.casting_interruptible AND READY(SPEAR_HAND_STRIKE) THEN\n    RETURN CAST(SPEAR_HAND_STRIKE)\nELSE IF PVP AND target.casting_interruptible AND READY(LEG_SWEEP) THEN\n    RETURN CAST(LEG_SWEEP)\nELSE IF READY(TOUCH_OF_DEATH) THEN\n    RETURN CAST(TOUCH_OF_DEATH)\nELSE IF BOSS AND READY(INVOKE_XUEN) THEN\n    RETURN CAST(INVOKE_XUEN)\nELSE IF BOSS AND READY(STORM_EARTH_AND_FIRE) THEN\n    RETURN CAST(STORM_EARTH_AND_FIRE)\nELSE IF PROC(WHIRLING_DRAGON_PUNCH) AND READY(WHIRLING_DRAGON_PUNCH) THEN\n    RETURN CAST(WHIRLING_DRAGON_PUNCH)\nELSE IF READY(CELESTIAL_CONDUIT) THEN\n    RETURN CAST(CELESTIAL_CONDUIT)\nELSE IF (PROC(SPINNING_CRANE_KICK) OR player.aura(DANCE_OF_CHI_JI).rem > 0) AND READY(SPINNING_CRANE_KICK) THEN\n    RETURN CAST(SPINNING_CRANE_KICK)\nELSE IF player.chi >= 5 AND READY(RISING_SUN_KICK) THEN\n    RETURN CAST(RISING_SUN_KICK)\nELSE IF player.chi >= 5 AND READY(FISTS_OF_FURY) THEN\n    RETURN CAST(FISTS_OF_FURY)\nELSE IF player.chi >= 5 AND enemies >= 3 AND READY(SPINNING_CRANE_KICK) THEN\n    RETURN CAST(SPINNING_CRANE_KICK)\nELSE IF player.chi >= 5 AND READY(BLACKOUT_KICK) THEN\n    RETURN CAST(BLACKOUT_KICK)\nELSE IF READY(STRIKE_OF_THE_WINDLORD) THEN\n    RETURN CAST(STRIKE_OF_THE_WINDLORD)\nELSE IF enemies <= 4 AND READY(RISING_SUN_KICK) THEN\n    RETURN CAST(RISING_SUN_KICK)\nELSE IF READY(FISTS_OF_FURY) THEN\n    RETURN CAST(FISTS_OF_FURY)\nELSE IF READY(RISING_SUN_KICK) THEN\n    RETURN CAST(RISING_SUN_KICK)\nELSE IF READY(SLICING_WINDS) THEN\n    RETURN CAST(SLICING_WINDS)\nELSE IF player.aura(TEACHINGS_OF_THE_MONASTERY).stacks >= 4 AND READY(BLACKOUT_KICK) THEN\n    RETURN CAST(BLACKOUT_KICK)\nELSE IF (PROC(BLACKOUT_KICK) OR player.aura(BLACKOUT_KICK_PROC).rem > 0) AND READY(BLACKOUT_KICK) THEN\n    RETURN CAST(BLACKOUT_KICK)\nELSE IF player.aura(THE_EMPERORS_CAPACITOR).stacks >= 20 AND READY(CRACKLING_JADE_LIGHTNING) THEN\n    RETURN CAST(CRACKLING_JADE_LIGHTNING)\nELSE IF enemies >= 3 AND player.chi >= 2 AND READY(SPINNING_CRANE_KICK) THEN\n    RETURN CAST(SPINNING_CRANE_KICK)\nELSE IF player.chi <= 3 AND READY(TIGER_PALM) THEN\n    RETURN CAST(TIGER_PALM)\nELSE IF READY(BLACKOUT_KICK) THEN\n    RETURN CAST(BLACKOUT_KICK)\nELSE IF READY(EXPEL_HARM) THEN\n    RETURN CAST(EXPEL_HARM)\nELSE\n    RETURN CAST(TIGER_PALM)\nEND IF\n",
["title"] = "8. Монах: Танцующий с ветром (ВВ — СТ / АоЕ)",
["userModified"] = false,
["id"] = "MONK_01_WW_PVE",
["class"] = "MONK",
["mode"] = "PVE",
},
["MAGE_04_FROST_PVE"] = {
["md"] = "# PROFILE: 2. Маг: Лёд (Фрост — СТ / АоЕ)\n# CLASS: MAGE\n# SPEC: Frost\n# MODE: PVE\n\n## SPELL_BOOK\nAURA FREEZING = ID:1221389,228358,205708 | AURA_UNIT:target | AURA_DUR:15 | NAME:\"Обледенение\",\"Замерзание\",\"Freezing\",\"Зимняя стужа\",\"Winter's Chill\"\nSPELL COUNTERSPELL = ID:2139 | NAME:\"Антимагия\",\"Counterspell\" | CD:24 | INTERRUPT:true | ICON:135856\nSPELL FROST_NOVA = ID:122,113724 | NAME:\"Кольцо льда\",\"Кольцо мороза\",\"Frost Nova\",\"Ring of Frost\" | CD:30 | PVP:true | ICON:135848\nSPELL ICY_VEINS = ID:12472 | AURA_ID:12472 | AURA_UNIT:player | AURA_DUR:20 | BURST:20 | BOSS:true | NAME:\"Стылая кровь\",\"Icy Veins\" | CD:120 | ICON:135838\nSPELL RAY_OF_FROST = ID:205021 | BOSS:true | NAME:\"Морозный луч\",\"Луч холода\",\"Ray of Frost\" | CD:60 | CHARGES:1 | STACKS:+3 | LOCK_CHANNEL:true | ICON:1698700\nSPELL COMET_STORM = ID:153595,455396 | NAME:\"Кометная буря\",\"Comet Storm\" | CD:30 | STACKS:+2 | PROC_ONLY:true | OVERRIDE_OF:RAY_OF_FROST | ICON:1033912\nSPELL GLACIAL_SPIKE = ID:199786,257537 | NAME:\"Ледниковый шип\",\"Черная стрела\",\"Glacial Spike\",\"Ebonbolt\" | CD:0 | STACKS:+2 | PROC_ONLY:true | OVERRIDE_OF:FROSTBOLT | ICON:1394891\nSPELL FLURRY = ID:44614 | NAME:\"Шквал\",\"Flurry\" | CD:30 | CHARGES:2 | HASTED_CD:true | STACKS:+2 | ICON:135859\nSPELL FROZEN_ORB = ID:84714 | NAME:\"Ледяной шар\",\"Мерзлая сфера\",\"Frozen Orb\" | CD:60 | STACKS:+2 | ICON:629077\nSPELL ICE_LANCE = ID:30455 | NAME:\"Ледяное копье\",\"Ice Lance\" | CD:0 | CONSUMES_STACKS:true | STACKS:-4 | ICON:135844\nSPELL BLIZZARD = ID:190356,1248829 | NAME:\"Снежная буря\",\"Blizzard\" | CD:12 | ICON:135858\nSPELL FROSTBOLT = ID:431044,116 | NAME:\"Ледяная стрела\",\"Стрела ледяного огня\",\"Frostbolt\",\"Frostfire Bolt\" | CD:0 | STACKS:+1 | ICON:135846\nSPELL ICE_BLOCK = ID:45438,414658 | NAME:\"Ледяная глыба\",\"Холодная хватка\",\"Ice Block\",\"Ice Cold\" | CD:240 | CHARGES:2 | ICON:135841\nSPELL ICE_BARRIER = ID:11426,235313,431038 | NAME:\"Ледяная преграда\",\"Пылающая преграда\",\"Пылающий барьер\",\"Ice Barrier\",\"Blazing Barrier\" | CD:25 | CHARGES:1 | ICON:135988\nSPELL ALTER_TIME = ID:342245,108978 | NAME:\"Манипуляции со временем\",\"Путешествие во времени\",\"Alter Time\" | CD:60 | ICON:609811\nSPELL COLD_SNAP = ID:235219,55342 | NAME:\"Холодная хватка\",\"Зеркальное изображение\",\"Cold Snap\",\"Mirror Image\" | CD:120 | ICON:135865\n\n## CHANNEL_POLICY\nPROTECT_CHANNEL: RAY_OF_FROST\n\n## TRACKERS\nTRACK_SAVES: ICE_BLOCK, ICE_BARRIER, ALTER_TIME, COLD_SNAP\nTRACK_CDS: ICY_VEINS, RAY_OF_FROST, FROZEN_ORB, FLURRY, COMET_STORM, COUNTERSPELL\nTRACK_DOTS: FREEZING\n\n## EMERGENCY_SAVE\nIF player.hp_percent <= 25 AND READY(ICE_BLOCK) THEN\n    RETURN EMERGENCY(ICE_BLOCK)\nELSE IF player.hp_percent <= 25 AND READY(ICE_BARRIER) THEN\n    RETURN EMERGENCY(ICE_BARRIER)\nEND IF\n\n## ROTATION_QUEUE\nIF target.casting_interruptible AND READY(COUNTERSPELL) THEN\n    RETURN CAST(COUNTERSPELL)\nELSE IF BOSS AND READY(ICY_VEINS) THEN\n    RETURN CAST(ICY_VEINS)\nELSE IF PVP AND READY(FROST_NOVA) THEN\n    RETURN CAST(FROST_NOVA)\nELSE IF PROC(COMET_STORM) AND READY(COMET_STORM) THEN\n    RETURN CAST(COMET_STORM)\nELSE IF PROC(GLACIAL_SPIKE) AND READY(GLACIAL_SPIKE) THEN\n    RETURN CAST(GLACIAL_SPIKE)\nELSE IF PROC(FLURRY) AND READY(FLURRY) THEN\n    RETURN CAST(FLURRY)\nELSE IF enemies >= 3 AND READY(FROZEN_ORB) THEN\n    RETURN CAST(FROZEN_ORB)\nELSE IF (enemies >= 3 OR PROC(BLIZZARD)) AND READY(BLIZZARD) THEN\n    RETURN CAST(BLIZZARD)\nELSE IF BOSS AND CHARGES(RAY_OF_FROST) >= 2 AND READY(RAY_OF_FROST) THEN\n    RETURN CAST(RAY_OF_FROST)\nELSE IF READY(FROZEN_ORB) THEN\n    RETURN CAST(FROZEN_ORB)\nELSE IF BOSS AND READY(RAY_OF_FROST) THEN\n    RETURN CAST(RAY_OF_FROST)\nELSE IF READY(FLURRY) THEN\n    RETURN CAST(FLURRY)\nELSE IF PROC(ICE_LANCE) AND READY(ICE_LANCE) THEN\n    RETURN CAST(ICE_LANCE)\nELSE IF target.aura(FREEZING).stacks >= 4 AND READY(ICE_LANCE) THEN\n    RETURN CAST(ICE_LANCE)\nELSE\n    RETURN CAST(FROSTBOLT)\nEND IF\n",
["title"] = "2. Маг: Лёд (Фрост — СТ / АоЕ)",
["userModified"] = false,
["id"] = "MAGE_04_FROST_PVE",
["class"] = "MAGE",
["mode"] = "PVE",
},
["DRUID_01_FERAL_PVE"] = {
["md"] = "# PROFILE: 5. Друид: Сила зверя (Кот — СТ / АоЕ)\n# CLASS: DRUID\n# SPEC: Feral\n# MODE: PVE\n\n## SPELL_BOOK\nSPELL SKULL_BASH = ID:106839 | NAME:\"Лобовая атака\",\"Skull Bash\" | CD:15 | INTERRUPT:true | ICON:236946\nSPELL MIGHTY_BASH = ID:5211,22570 | NAME:\"Мощное оглушение\",\"Калечение\",\"Mighty Bash\",\"Maim\" | CD:60 | PVP:true | ICON:132114\nSPELL TIGERS_FURY = ID:5217 | AURA_ID:5217 | AURA_UNIT:player | AURA_DUR:20 | BURST:20 | NAME:\"Тигриное неистовство\",\"Tiger's Fury\" | CD:30 | ICON:132242\nSPELL BERSERK = ID:106951,102543,343223 | AURA_ID:106951,102543 | AURA_UNIT:player | AURA_DUR:15 | BURST:15 | BOSS:true | NAME:\"Берсерк\",\"Воплощение: аватара Ашаманы\",\"Berserk\",\"Incarnation: Avatar of Ashamane\" | CD:120 | ICON:236149\nSPELL CONVOKE_THE_SPIRITS = ID:391528 | BOSS:true | NAME:\"Созыв духов\",\"Convoke the Spirits\" | CD:120 | LOCK_CHANNEL:true | ICON:3636839\nSPELL FERAL_FRENZY = ID:274837,1243807 | NAME:\"Дикое бешенство\",\"Безумное бешенство\",\"Feral Frenzy\",\"Frantic Frenzy\" | CD:45 | GAIN:100 | ICON:2065580\nSPELL RAKE = ID:1822 | AURA_ID:155722 | AURA_DUR:15 | NAME:\"Глубокая рана\",\"Rake\" | CD:0 | GAIN:20 | ICON:132122\nSPELL PRIMAL_WRATH = ID:285381 | AURA_ID:1079 | AURA_DUR:12 | NAME:\"Первобытный гнев\",\"Primal Wrath\" | CD:0 | COST:80 | SPENDER:true | ICON:2065583\nSPELL RIP = ID:1079 | AURA_ID:1079 | AURA_DUR:24 | NAME:\"Разорвать\",\"Rip\" | CD:0 | COST:80 | SPENDER:true | ICON:132152\nSPELL FEROCIOUS_BITE = ID:22568,441583,441591 | NAME:\"Свирепый укус\",\"Опустошение\",\"Ferocious Bite\",\"Ravage\" | CD:0 | COST:80 | SPENDER:true | ICON:132127\nSPELL SWIPE = ID:106785,213764 | NAME:\"Размах\",\"Swipe\" | CD:0 | GAIN:20 | ICON:132141\nSPELL SHRED = ID:5221 | NAME:\"Полоснуть\",\"Shred\" | CD:0 | GAIN:20 | FILLER_INTERRUPTIBLE:true | ICON:136231\nSPELL SURVIVAL_INSTINCTS = ID:61336 | NAME:\"Инстинкты выживания\",\"Survival Instincts\" | CD:180 | CHARGES:2 | ICON:236169\nSPELL BARKSKIN = ID:22812 | NAME:\"Дубовая кожа\",\"Barkskin\" | CD:60 | ICON:136097\nSPELL REGROWTH = ID:8936 | AURA_ID:69369 | AURA_UNIT:player | AURA_DUR:12 | NAME:\"Восстановление\",\"Regrowth\",\"Стремительность хищника\",\"Predatory Swiftness\" | CD:0 | ICON:136085\nSPELL FRENZIED_REGENERATION = ID:22842,108238 | NAME:\"Неистовое восстановление\",\"Обновление\",\"Frenzied Regeneration\",\"Renewal\" | CD:36 | ICON:132091\n\n## CHANNEL_POLICY\nPROTECT_CHANNEL: CONVOKE_THE_SPIRITS\n\n## TRACKERS\nTRACK_SAVES: SURVIVAL_INSTINCTS, BARKSKIN, REGROWTH, FRENZIED_REGENERATION\nTRACK_CDS: BERSERK, CONVOKE_THE_SPIRITS, TIGERS_FURY, FERAL_FRENZY, SKULL_BASH\nTRACK_DOTS: RAKE, RIP\n\n## EMERGENCY_SAVE\nIF player.hp_percent <= 25 AND READY(SURVIVAL_INSTINCTS) THEN\n    RETURN EMERGENCY(SURVIVAL_INSTINCTS)\nELSE IF player.hp_percent <= 45 AND PROC(REGROWTH) AND READY(REGROWTH) THEN\n    RETURN EMERGENCY(REGROWTH)\nELSE IF player.hp_percent <= 35 AND READY(FRENZIED_REGENERATION) THEN\n    RETURN EMERGENCY(FRENZIED_REGENERATION)\nELSE IF player.hp_percent <= 40 AND READY(BARKSKIN) THEN\n    RETURN EMERGENCY(BARKSKIN)\nEND IF\n\n## ROTATION_QUEUE\nIF target.casting_interruptible AND READY(SKULL_BASH) THEN\n    RETURN CAST(SKULL_BASH)\nELSE IF PVP AND READY(MIGHTY_BASH) THEN\n    RETURN CAST(MIGHTY_BASH)\nELSE IF player.stealthed AND READY(RAKE) THEN\n    RETURN CAST(RAKE)\nELSE IF PROC(FEROCIOUS_BITE) AND READY(FEROCIOUS_BITE) THEN\n    RETURN CAST(FEROCIOUS_BITE)\nELSE IF player.energy <= 40 AND READY(TIGERS_FURY) THEN\n    RETURN CAST(TIGERS_FURY)\nELSE IF BOSS AND READY(BERSERK) THEN\n    RETURN CAST(BERSERK)\nELSE IF enemies >= 2 AND target.aura(RIP).rem <= 1 AND USABLE(PRIMAL_WRATH) THEN\n    RETURN CAST(PRIMAL_WRATH)\nELSE IF target.aura(RIP).rem <= 1 AND USABLE(RIP) THEN\n    RETURN CAST(RIP)\nELSE IF USABLE(FEROCIOUS_BITE) THEN\n    RETURN CAST(FEROCIOUS_BITE)\nELSE IF target.aura(RAKE).rem <= 1 AND READY(RAKE) THEN\n    RETURN CAST(RAKE)\nELSE IF player.combo_points <= 2 AND READY(FERAL_FRENZY) THEN\n    RETURN CAST(FERAL_FRENZY)\nELSE IF BOSS AND player.combo_points <= 2 AND READY(CONVOKE_THE_SPIRITS) THEN\n    RETURN CAST(CONVOKE_THE_SPIRITS)\nELSE IF enemies >= 2 AND READY(SWIPE) THEN\n    RETURN CAST(SWIPE)\nELSE\n    RETURN CAST(SHRED)\nEND IF\n",
["title"] = "5. Друид: Сила зверя (Кот — СТ / АоЕ)",
["userModified"] = false,
["id"] = "DRUID_01_FERAL_PVE",
["class"] = "DRUID",
["mode"] = "PVE",
},
